package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.deser.ValueInstantiator;
import com.fasterxml.jackson.databind.deser.impl.TypeDeserializer;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.ValueInstantiator;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.mockito.Mockito.verifyNoInteractions;

/**
 * Unit tests for AtomicReferenceDeserializer#getNullValue
 */
public class AtomicReferenceDeserializer_getNullValue_TriageGen1Test {

    private AtomicReferenceDeserializer deserializer;

    @Mock
    private JavaType fullType;

    @Mock
    private ValueInstantiator inst;

    @Mock
    private TypeDeserializer typeDeser;

    @Mock
    private StdDeserializer<?> deser;

    @Mock
    private DeserializationContext ctxt;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        deserializer = new AtomicReferenceDeserializer(fullType, inst, typeDeser, deser);
    }

    @Test
    public void testGetNullValue_ReturnsNewAtomicReference() throws Exception {
        // Act
        AtomicReference<Object> result = deserializer.getNullValue(ctxt);

        // Assert
        Assert.assertNotNull("The returned AtomicReference should not be null", result);
        Assert.assertNull("The content of the AtomicReference should be null", result.get());

        // Verify that the context was not interacted with as the implementation is a simple instantiation
        verifyNoInteractions(ctxt);
    }

    @Test
    public void testGetNullValue_MultipleCallsReturnDifferentInstances() throws Exception {
        // Act
        AtomicReference<Object> firstCall = deserializer.getNullValue(ctxt);
        AtomicReference<Object> secondCall = deserializer.getNullValue(ctxt);

        // Assert
        Assert.assertNotNull(firstCall);
        Assert.assertNotNull(secondCall);
        Assert.assertNotSame("Each call should return a new instance of AtomicReference", firstCall, secondCall);
    }
}
